     1	#pragma once
     2	
     3	// Answers OrcaSlicer's own dialogs on behalf of an operation the person has
     4	// already decided through an approval card. Orca asks its questions in
     5	// modals deep inside its load paths; rather than a flag at every site, the
     6	// one place they all open (DPIAware::ShowModal) asks the innermost scope
     7	// here, and the scope records each question and the answer it gave.
     8	//
     9	// GUI thread only. Scopes nest; the innermost answers.
    10	
    11	#include <wx/string.h>
    12	
    13	#include <functional>
    14	#include <string>
    15	#include <vector>
    16	
    17	class wxWindow;
    18	
    19	namespace Slic3r::GUI::JusPrin::Workspace {
    20	
    21	struct ModalRecord
    22	{
    23	    std::string title; // UTF-8, as the dialog is titled in the current language
    24	    int         answer{0};
    25	};
    26	
    27	class ScopedModalAnswers
    28	{
    29	public:
    30	    // Returns the wx id the dialog's ShowModal would have returned.
    31	    using Decide = std::function<int(wxWindow& dialog, const wxString& title)>;
    32	
    33	    explicit ScopedModalAnswers(Decide decide);
    34	    ~ScopedModalAnswers();
    35	    ScopedModalAnswers(const ScopedModalAnswers&)            = delete;
    36	    ScopedModalAnswers& operator=(const ScopedModalAnswers&) = delete;
    37	
    38	    const std::vector<ModalRecord>& records() const { return m_records; }
    39	
    40	private:
    41	    friend bool answer_through_scope(wxWindow& dialog, int& answer);
    42	    Decide                   m_decide;
    43	    std::vector<ModalRecord> m_records;
    44	    ScopedModalAnswers*      m_outer{nullptr};
    45	};
    46	
    47	} // namespace Slic3r::GUI::JusPrin::Workspace
    48	#include "ModalAnswers.hpp"
    49	
    50	#include <wx/thread.h>
    51	#include <wx/toplevel.h>
    52	#include <wx/window.h>
    53	
    54	namespace Slic3r::GUI::JusPrin::Workspace {
    55	
    56	namespace {
    57	ScopedModalAnswers* g_innermost = nullptr;
    58	}
    59	
    60	ScopedModalAnswers::ScopedModalAnswers(Decide decide) : m_decide(std::move(decide)), m_outer(g_innermost)
    61	{
    62	    wxASSERT(wxIsMainThread());
    63	    g_innermost = this;
    64	}
    65	
    66	ScopedModalAnswers::~ScopedModalAnswers()
    67	{
    68	    wxASSERT(g_innermost == this);
    69	    g_innermost = m_outer;
    70	}
    71	
    72	bool answer_through_scope(wxWindow& dialog, int& answer)
    73	{
    74	    if (g_innermost == nullptr || !wxIsMainThread())
    75	        return false;
    76	    const wxTopLevelWindow* window = dynamic_cast<wxTopLevelWindow*>(&dialog);
    77	    const wxString          title  = window != nullptr ? window->GetTitle() : wxString();
    78	    answer = g_innermost->m_decide(dialog, title);
    79	    g_innermost->m_records.push_back({title.ToUTF8().data(), answer});
    80	    return true;
    81	}
    82	
    83	} // namespace Slic3r::GUI::JusPrin::Workspace
    84	
    85	namespace Slic3r::GUI {
    86	
    87	bool answer_modal(wxWindow& dialog, int& answer)
    88	{
    89	    return JusPrin::Workspace::answer_through_scope(dialog, answer);
    90	}
    91	
    92	} // namespace Slic3r::GUI
